```python
import numpy as np
from scipy.spatial.distance import pdist, squareform

def minesweeper_homology(board):
    n = len(board)
    d = np.sum(np.abs(pdist(board)))
    st = SimplexTree()
    for i in range(n):
        for j in range(n):
            st.insert([(i,j)], filtration=d)
    ph = PersistentHomology()
    ph.build(st)
    return ph.persistence()

def minesweeper_solver(board):
    homology = minesweeper_homology(board)
    mines = []
    for h in homology:
        if h[1]-h[0]==1:
            mines.append(h[0])
    for mine in mines:
        i, j = mine
        board[i][j]=-1
    return board
```
